#!/usr/bin/env python3
"""Generate kp.events constants and namespace migration documentation.

The empty alias artifact is retained for generated-file compatibility only; no
runtime code consumes it and API version 2 exports no compatibility aliases.
"""
from __future__ import annotations

import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "data" / "api_aliases.toml"
EVENTS_SRC = ROOT / "data" / "events.toml"
GEN = ROOT / "src" / "generated"
DOCS = ROOT / "docs" / "api-dialects.md"

BANNER_ALIASES = (
    "// Generated by tools/gen_compat.py from data/api_aliases.toml.\n"
    "// Do not edit; edit the table and regenerate.\n"
)
BANNER_EVENTS = (
    "// Generated by tools/gen_compat.py from data/api_aliases.toml "
    "and data/events.toml.\n"
    "// Do not edit; edit the tables and regenerate.\n"
)


def event_constant(e: dict) -> str:
    return e.get("constant") or e.get("sapp") or ""


def load_aliases() -> dict:
    with SRC.open("rb") as fh:
        doc = tomllib.load(fh)

    problems = []
    seen = {}
    for a in doc.get("alias", []):
        for k in ("canonical", "alias", "dialect"):
            if not a.get(k):
                problems.append(f"alias entry missing {k}: {a}")
        if a["alias"] in seen and seen[a["alias"]] != a["canonical"]:
            problems.append(f"{a['alias']} aliases both {seen[a['alias']]} "
                            f"and {a['canonical']}")
        seen[a["alias"]] = a["canonical"]
        if a["alias"] == a["canonical"]:
            problems.append(f"{a['alias']} aliases itself")
    names = set()
    for e in doc.get("event_alias", []):
        name = event_constant(e)
        if not name:
            problems.append(f"event entry with no constant: {e}")
        if name in names:
            problems.append(f"duplicate event constant {name}")
        names.add(name)
    if problems:
        for p in problems:
            print(f"error: {p}", file=sys.stderr)
        raise SystemExit(1)
    return doc


def load_catalog_events() -> list[str]:
    with EVENTS_SRC.open("rb") as fh:
        doc = tomllib.load(fh)
    names = []
    seen = set()
    for e in doc.get("event", []):
        n = e.get("lua_name")
        if n and n not in seen:
            seen.add(n)
            names.append(n)
    return names


def flatten_events(doc: dict) -> list[dict]:
    events = []
    mapped = set()
    for e in doc.get("event_alias", []):
        name = event_constant(e)
        events.append({
            "name": name,
            "lua_name": e.get("lua_name") or "",
            "note": e.get("note") or "",
        })
        mapped.add(name)
        if e.get("lua_name"):
            mapped.add(e["lua_name"])
    for n in load_catalog_events():
        if n in mapped:
            continue
        events.append({"name": n, "lua_name": n, "note": ""})
    return events


def gen_aliases(doc: dict) -> str:
    out = [BANNER_ALIASES, "// clang-format off"]
    for a in doc["alias"]:
        out.append(f'{{"{a["alias"]}", "{a["canonical"]}", "{a["dialect"]}"}},')
    out.append("// clang-format on")
    return "\n".join(out) + "\n"


def gen_events(events: list[dict]) -> str:
    out = [BANNER_EVENTS, "// clang-format off"]
    for i, e in enumerate(events):
        note = (e.get("note") or "").replace('"', "'")
        out.append(f'{{"{e["name"]}", "{e["lua_name"]}", {i}, "{note}"}},')
    out.append("// clang-format on")
    return "\n".join(out) + "\n"


def gen_docs(doc: dict, events: list[dict]) -> str:
    lines = ["# Native namespace and callback migration", "",
             "Generated from `data/api_aliases.toml` and `data/events.toml`.", "",
             "API version 2 has two public roots: `nwscript.call(name, ...)` for direct "
             "engine routines and `kp` for every native host facility.", "",
             "The former kotor root, bare host functions, underscored aliases, "
             "cb/events globals, host identity globals and host bit32 alias are removed. "
             "Use `kp.mem.readbyte`, `kp.registertimer` and `kp.diagnostic`. "
             "The engine logarithm is `nwscript.call('log', value)`.", "",
             "Bridge context is `nwscript.with_caller(object_id, fn, ...)`; "
             "the last dispatch receipt is `nwscript.last_trace()`. The old native "
             "log, as and last_routine_trace members have no compatibility aliases.", "",
             "Native object conveniences such as `kp.obj.position` retain distinct "
             "names. Their C++ implementation explicitly consumes `api::find` and "
             "`api::call`; they require the VM backend for engine operations without "
             "exporting engine routine names or creating the nwscript root.", "",
             "Lua's standard `print` remains unchanged. `kp.print(...)` writes host "
             "diagnostics; console and harness states capture that native output.", "",
             "Host metadata is `kp.host`, `kp.serverapp`, `kp.game`, "
             "`kp.api_version` (2), `kp.version`, `kp.gamedir()` and `kp.time()`.", "",
             "## Explicit event registration", "", "```lua",
             "kp.events.register(kp.events.OnTick, function(tick, relevant)",
             "    -- ...", "end)",
             "kp.events.unregister(kp.events.OnTick)", "```", "",
             "Registration accepts a function or a script-owned global function name. "
             "The dispatcher still discovers global On* callbacks for legacy compatibility. "
             "Explicit registration wins; unregister restores a discovered global handler. "
             "Script-owned `priority` remains loader metadata. Neither behavior exports "
             "a bare host facility.", "",
             f"The {len(events)} event constants below come from the event catalog.", "",
             "| constant | dispatched event |", "|---|---|"]
    for e in events:
        lines.append(f"| `kp.events.{e['name']}` | `{e['lua_name']}` |")
    return "\n".join(lines) + "\n"


def main() -> int:
    doc = load_aliases()
    events = flatten_events(doc)
    GEN.mkdir(parents=True, exist_ok=True)
    (GEN / "compat_aliases.inc").write_text(gen_aliases(doc))
    (GEN / "compat_events.inc").write_text(gen_events(events))
    DOCS.write_text(gen_docs(doc, events))

    mapped = sum(1 for e in events if e.get("lua_name"))
    canon = len({a["canonical"] for a in doc["alias"]})
    print(f"{len(doc['alias'])} aliases over {canon} functions, "
          f"{len(events)} event constants ({mapped} mapped) "
          f"-> compat_aliases.inc, compat_events.inc, docs/api-dialects.md")
    return 0


if __name__ == "__main__":
    sys.exit(main())
